import React, { useEffect, useCallback } from "react";
import { View, Text, StyleSheet, Pressable, useWindowDimensions } from "react-native";
import { GestureDetector, Gesture } from "react-native-gesture-handler";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  runOnJS,
} from "react-native-reanimated";
import Svg, { Rect, Text as SvgText } from "react-native-svg";
import { colors, typography, radii, spacing } from "@resto-plus/ui-luxury";
import type { Table, ElementDecor, StatutTable } from "@resto-plus/types";

interface PlanSalleScreenProps {
  nomSalle: string;
  tables: Table[];
  decor: ElementDecor[];
  editable: boolean;
  onTablePress: (tableId: string) => void;
  onTableMove: (tableId: string, x: number, y: number) => void;
}

const STATUT_COLOR: Record<StatutTable, string> = {
  libre: colors.statusFree,
  occupee: colors.statusOccupied,
  reservee: colors.statusReserved,
  a_nettoyer: colors.textMuted,
};

const DECOR_LABEL: Record<string, string> = {
  bar: "BAR",
  entree: "ENTRÉE",
  cuisine: "CUISINE",
  mur: "",
};

// ─── Token de table ──────────────────────────────────────────────────────────

function TableToken({
  table,
  editable,
  onPress,
  onMove,
}: {
  table: Table;
  editable: boolean;
  onPress: () => void;
  onMove: (x: number, y: number) => void;
}) {
  const translateX = useSharedValue(table.x);
  const translateY = useSharedValue(table.y);

  // Sync avec les props quand le store met à jour les coordonnées
  useEffect(() => {
    translateX.value = table.x;
    translateY.value = table.y;
  }, [table.x, table.y, translateX, translateY]);

  const commitPosition = useCallback(
    (x: number, y: number) => onMove(x, y),
    [onMove]
  );

  const pan = Gesture.Pan()
    .enabled(editable)
    .onUpdate((e) => {
      translateX.value = table.x + e.translationX;
      translateY.value = table.y + e.translationY;
    })
    .onEnd(() => {
      runOnJS(commitPosition)(translateX.value, translateY.value);
    });

  const tap = Gesture.Tap().onEnd(() => {
    runOnJS(onPress)();
  });

  const gesture = editable ? Gesture.Race(pan, tap) : tap;

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [
      { translateX: translateX.value },
      { translateY: translateY.value },
      { rotate: `${table.rotation}deg` },
    ],
  }));

  const isRonde = table.forme === "ronde";
  const statutColor = STATUT_COLOR[table.statut];

  return (
    <GestureDetector gesture={gesture}>
      <Animated.View
        style={[
          styles.table,
          animatedStyle,
          {
            width: table.largeur,
            height: table.hauteur,
            borderRadius: isRonde ? table.largeur / 2 : radii.card,
            borderColor: statutColor,
            position: "absolute",
            top: 0,
            left: 0,
          },
        ]}
      >
        <Text style={[styles.tableLabel, { color: statutColor }]}>
          {table.capacite}
        </Text>
      </Animated.View>
    </GestureDetector>
  );
}

// ─── Screen principal ─────────────────────────────────────────────────────────

export function PlanSalleScreen({
  nomSalle,
  tables,
  decor,
  editable,
  onTablePress,
  onTableMove,
}: PlanSalleScreenProps) {
  const { width } = useWindowDimensions();
  const canvasWidth = width - spacing.lg * 2;
  const canvasHeight = canvasWidth * 1.3; // ratio 3:4

  const validCount = tables.filter((t) => t.statut === "libre").length;
  const occupeCount = tables.filter((t) => t.statut === "occupee").length;

  return (
    <View style={styles.container}>
      <View style={[styles.canvas, { width: canvasWidth, height: canvasHeight }]}>
        {/* Éléments de décor en SVG */}
        <Svg width="100%" height="100%" style={StyleSheet.absoluteFill}>
          {decor.map((el) => (
            <React.Fragment key={el.id}>
              <Rect
                x={el.x}
                y={el.y}
                width={el.largeur}
                height={el.hauteur}
                rx={3}
                fill={colors.creamBorder}
              />
              {DECOR_LABEL[el.type] ? (
                <SvgText
                  x={el.x + el.largeur / 2}
                  y={el.y + el.hauteur / 2 + 4}
                  textAnchor="middle"
                  fontSize={7}
                  letterSpacing={1}
                  fill={colors.textMuted}
                >
                  {DECOR_LABEL[el.type]}
                </SvgText>
              ) : null}
            </React.Fragment>
          ))}
        </Svg>

        {/* Tables interactives */}
        {tables.map((table) => (
          <TableToken
            key={table.id}
            table={table}
            editable={editable}
            onPress={() => onTablePress(table.id)}
            onMove={(x, y) => onTableMove(table.id, x, y)}
          />
        ))}
      </View>

      {/* Stats + légende */}
      <View style={styles.footer}>
        <View style={styles.stats}>
          <Text style={styles.statItem}>
            <Text style={styles.statNum}>{validCount}</Text> libre{validCount > 1 ? "s" : ""}
          </Text>
          <Text style={styles.statSep}>·</Text>
          <Text style={styles.statItem}>
            <Text style={styles.statNum}>{occupeCount}</Text> occupée{occupeCount > 1 ? "s" : ""}
          </Text>
          <Text style={styles.statSep}>·</Text>
          <Text style={styles.statItem}>
            <Text style={styles.statNum}>{tables.length}</Text> au total
          </Text>
        </View>

        <View style={styles.legend}>
          <LegendItem couleur={colors.statusFree} label="Libre" />
          <LegendItem couleur={colors.statusOccupied} label="Occupée" />
          <LegendItem couleur={colors.statusReserved} label="Réservée" />
          <LegendItem couleur={colors.textMuted} label="À nettoyer" />
        </View>
      </View>
    </View>
  );
}

function LegendItem({ couleur, label }: { couleur: string; label: string }) {
  return (
    <View style={styles.legendItem}>
      <View style={[styles.legendDot, { backgroundColor: couleur }]} />
      <Text style={styles.legendLabel}>{label}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: colors.cream,
    padding: spacing.lg,
  },
  canvas: {
    backgroundColor: colors.creamLight,
    borderWidth: 1,
    borderColor: colors.creamBorder,
    borderRadius: radii.sharp,
    marginBottom: spacing.md,
    overflow: "hidden",
  },
  table: {
    backgroundColor: colors.cream,
    borderWidth: 1.5,
    alignItems: "center",
    justifyContent: "center",
  },
  tableLabel: {
    fontFamily: typography.serif,
    fontSize: 12,
  },
  footer: {
    gap: spacing.sm,
  },
  stats: {
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
    gap: spacing.xs,
  },
  statItem: {
    fontSize: 11,
    color: colors.textMuted,
  },
  statNum: {
    fontFamily: typography.serif,
    color: colors.navy,
    fontSize: 12,
  },
  statSep: {
    color: colors.creamBorder,
    fontSize: 12,
  },
  legend: {
    flexDirection: "row",
    justifyContent: "center",
    gap: spacing.md,
    flexWrap: "wrap",
  },
  legendItem: {
    flexDirection: "row",
    alignItems: "center",
    gap: 5,
  },
  legendDot: {
    width: 7,
    height: 7,
    borderRadius: 4,
  },
  legendLabel: {
    fontSize: 10,
    color: colors.textMuted,
  },
});
